let raw = $json.output[0].content[0].text;

if (typeof raw !== "string") {
  raw = JSON.stringify(raw);
}

raw = raw.trim();

if (raw.startsWith("```json")) {
  raw = raw.replace(/^```json\s*/, "").replace(/\s*```$/, "");
} else if (raw.startsWith("```")) {
  raw = raw.replace(/^```\s*/, "").replace(/\s*```$/, "");
}

const parsed = JSON.parse(raw);

return {
  json: Array.isArray(parsed) ? { items: parsed } : parsed
};

const lead = $items("normalize lead", 0, 0)[0]?.json ?? {};
const contact = $json.person ?? $json ?? {};

const companyFromLead = (
  lead.company_name ??
  lead.company_name_clean ??
  lead["Company Name"] ??
  ""
).toString().trim();

const companyFromOrg = (
  contact.organization?.name ??
  $json.organization?.name ??
  ""
).toString().trim();

const organizationCountry = (
  contact.organization?.country ??
  contact.country ??
  $json.organization?.country ??
  $json.country ??
  ""
).toString().trim();

const contactCountryValue = (
  contact.country ??
  $json.country ??
  ""
).toString().trim();

const email = (
  contact.email ??
  $json.email ??
  ""
).toString().trim();

const domain = email.includes("@")
  ? email.split("@")[1].toLowerCase().trim()
  : "";

const companyFromDomain = domain
  ? domain
      .replace(/^www\./i, "")
      .replace(/\.(com|de|ch|at|net|org|io|co\.uk)$/i, "")
      .replace(/[-_]/g, " ")
      .trim()
  : "";

const companyName = (
  companyFromLead ||
  companyFromOrg ||
  companyFromDomain
).trim();

const websiteUrl = (
  lead.website_url ??
  lead["Website URL"] ??
  (domain ? `https://${domain}` : "")
).toString().trim();

const firstName = (
  contact.first_name ??
  $json.first_name ??
  ""
).toString().trim();

const lastName = (
  contact.last_name ??
  $json.last_name ??
  ""
).toString().trim();

const fullName = (
  contact.name ??
  $json.name ??
  `${firstName} ${lastName}`
).toString().trim();

const title = (
  contact.title ??
  $json.title ??
  ""
).toString().trim();

return {
  json: {
    company_name: companyName,
    website_url: websiteUrl,
    contact_first_name: firstName,
    contact_last_name: lastName,
    contact_full_name: fullName,
    contact_title: title,
    contact_email: email,
    debug_company_name: companyName,
    debug_contact_email: email,
    debug_email_domain: domain,
    organization_country: organizationCountry,
    contact_country: contactCountryValue
  }
};

const possibleValues = [
  $json.text,
  $json.output_text,
  $json.message,
  $json.response,
  $json.content?.[0]?.text,
  $json.content?.[0]?.content?.[0]?.text,
  $json.output?.[0]?.content?.[0]?.text,
  $json.response?.output?.[0]?.content?.[0]?.text,
  $json.data?.[0]?.content?.[0]?.text,
];

let raw = "";

for (const value of possibleValues) {
  if (typeof value === "string" && value.trim()) {
    raw = value.trim();
    break;
  }
}

let parsed = {};

if (raw) {
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    const match = raw.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        parsed = JSON.parse(match[0]);
      } catch (e2) {
        parsed = {};
      }
    }
  }
}

return {
  json: {
    language: parsed.language === "de" ? "de" : "en",
    salutation: (parsed.salutation ?? "").toString().trim(),
    subject: (parsed.subject ?? "").toString().trim(),
    company_intro: (parsed.company_intro ?? "").toString().trim()
  }
};

const prep = $items("prepare mail input", 0, 0)[0]?.json ?? {};
const gpt = $items("parse gpt output", 0, 0)[0]?.json ?? {};

let shop = {};
try {
  shop = $items("build shop context", 0, 0)[0]?.json ?? {};
} catch (e) {
  shop = {};
}

let langSource = {};
try {
  langSource = $items("language_guess1", 0, 0)[0]?.json ?? {};
} catch (e) {
  try {
    langSource = $items("language_guess", 0, 0)[0]?.json ?? {};
  } catch (e2) {
    langSource = {};
  }
}

const language = langSource.language_guess === "de" ? "de" : "en";

const companyName = (prep.company_name || "").trim();
const contactEmail = (prep.contact_email || "").trim();
const firstName = (prep.contact_first_name || "").trim();

const subject = (gpt.subject || `Your Company x ${companyName || "Unternehmen"}`).trim();

const salutation = (
  gpt.salutation ||
  (language === "de"
    ? "Guten Tag,"
    : (firstName ? `Hello ${firstName},` : "Hello,"))
).trim();

const pageTitle = (shop.page_title || "").trim();
const metaDescription = (shop.meta_description || "").trim();
const h1 = (shop.h1 || "").trim();
const websiteText = (shop.website_text || "").trim();

let companyIntro = (gpt.company_intro || "").trim();

if (!companyIntro) {
  const hasWebsiteSignals = !!(pageTitle || metaDescription || h1 || websiteText);

  if (language === "de") {
    if (hasWebsiteSignals) {
      companyIntro = `ich habe mir ${companyName} angesehen. Dabei wirkt der Auftritt insgesamt klar und gut strukturiert. Gerade an den Stellen, an denen Besucher vom ersten Interesse in den passenden nächsten Schritt geführt werden, liegen aus meiner Sicht oft gute Hebel.`;
    } else {
      companyIntro = `ich habe mir ${companyName} angesehen. Dabei hatte ich das Gefühl, dass schon vieles gut angelegt ist. Gerade in der Nutzerführung und in den Einstiegen liegen aus meiner Sicht oft gute Hebel, um noch mehr aus bestehendem Traffic herauszuholen.`;
    }
  } else {
    if (hasWebsiteSignals) {
      companyIntro = `I took a look at ${companyName}. The overall setup already feels clear and well structured. In my experience, some of the best opportunities usually sit in how visitors are guided from initial interest to the right next step.`;
    } else {
      companyIntro = `I took a look at ${companyName}. My impression was that a lot is already set up well. At the same time, there are often good opportunities in guidance and entry points to get more out of existing traffic.`;
    }
  }
}

let body = "";

if (language === "de") {
  body = `${salutation}

ich hoffe, es geht Ihnen gut.

${companyIntro}

Kurz zu mir:
Ich bin Your Name, Sales Executive Partner bei Your Company. Wir unterstützen Marken dabei, Shops und Websites in den Bereichen Nutzerführung, Performance und Markenwirkung so zu optimieren, dass sie messbar besser performen unter anderem für several well-known brands sowie viele weitere.

Gerne zeige ich Ihnen in einem unverbindlichen 15-minütigen Erstgespräch 2–3 konkrete Ansatzpunkte, die ich speziell bei Ihnen sehe und mit denen sich meist mehr aus dem bestehenden Traffic holen lässt ohne direkt mehr Werbebudget einzusetzen.

Beste Grüße aus Your address

Your Name
Sales Executive Partner
-
Your Company
you@yourcompany.com
www.Your Company.me
-
Instagram: www.instagram.com/Your Company.me
Your Address`;
} else {
  body = `${salutation}

I hope you're well.

${companyIntro}

Briefly about me:
I’m Your Name, Sales Executive Partner at Your Company. We help brands improve their shops and websites so user guidance, performance and brand impact come together more effectively including for several well-known brands and many others.

I'd be happy to share 2–3 concrete ideas I see specifically for your setup in a short, no-obligation 15-minute introductory call often helping brands get more out of existing traffic without simply increasing ad spend.

Best regards from Your address

Your Name
Sales Executive Partner
-
Your Company
you@yourcompany.com
www.Your Company.me
-
Instagram: www.instagram.com/Your Company.me
`;
}

return {
  json: {
    language,
    salutation,
    subject,
    company_intro: companyIntro,
    body,
    contact_email: contactEmail,
    company_name: companyName
  }
};

function normalizeUrl(raw) {
  try {
    const value = String(raw || '').trim();
    if (!value) {
      return {
        website_url: '',
        website_host: '',
        brand_guess: ''
      };
    }

    const withProto = value.startsWith('http') ? value : `https://${value}`;
    const u = new URL(withProto);
    const host = u.hostname.toLowerCase().replace(/^www\./, '');

    const firstLabel = host.split('.')[0] || '';
    const brandGuess = firstLabel.replace(/[-_]+/g, ' ').trim();

    return {
      website_url: u.origin,
      website_host: host,
      brand_guess: brandGuess
    };
  } catch {
    return {
      website_url: '',
      website_host: '',
      brand_guess: ''
    };
  }
}

function cleanCompanyName(name) {
  return String(name || '')
    .trim()
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .replace(/\/.*$/, '')
    .trim();
}

const raw = $json['Company Name'] || '';
const rawString = String(raw).trim();

const isUrlLike =
  /^https?:\/\//i.test(rawString) ||
  /^www\./i.test(rawString) ||
  /^[a-z0-9-]+\.[a-z]{2,}/i.test(rawString);

const norm = isUrlLike
  ? normalizeUrl(rawString)
  : {
      website_url: '',
      website_host: '',
      brand_guess: cleanCompanyName(rawString)
    };

return {
  json: {
    ...$json,

    original_company_field: rawString,

    company_name: norm.brand_guess || cleanCompanyName(rawString),
    company_name_clean: norm.brand_guess || cleanCompanyName(rawString),

    website_url: $json.website_url || norm.website_url,
    website_host: norm.website_host,
    brand_guess: norm.brand_guess,

    lead_input_was_url: isUrlLike
  }
};

const people = ($json.people || []).slice(0, 10);

const contacts_text = people.map((p, i) => {
  const firstName = p.first_name || "";
  const lastName = p.last_name || p.last_name_obfuscated || "";
  const title = p.title || "";
  const hasEmail = p.has_email ? "Ja" : "Nein";
  const hasDirectPhone = p.has_direct_phone ? "Ja" : "Nein";
  const orgName = p.organization?.name || "";
  const personId = p.id || "";

  return `${i + 1}. ${firstName} ${lastName} | Titel: ${title} | Email verfügbar: ${hasEmail} | Direktnummer verfügbar: ${hasDirectPhone} | Unternehmen: ${orgName} | Apollo Person ID: ${personId}`;
}).join("\n");

return {
  json: {
    company_name: $json.people?.[0]?.organization?.name || "",
    contacts_text
  }
};

