let prep = {};

try {
  prep = $items("parse web search output", 0, 0)[0]?.json ?? {};
} catch (e) {
  prep = $items("prepare mail input", 0, 0)[0]?.json ?? {};
}

const website = $json ?? {};

const html =
  website.body ??
  website.data ??
  website.responseBody ??
  website.content ??
  website.html ??
  "";

const htmlString = (html ?? "").toString();

const blockedSignals = [
  "just a moment",
  "cloudflare",
  "attention required",
  "cf-chl",
  "enable javascript and cookies"
];

const websiteBlocked = blockedSignals.some(signal =>
  htmlString.toLowerCase().includes(signal)
);

const getTitle = (input) => {
  const match = input.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  return match ? match[1].replace(/\s+/g, " ").trim() : "";
};

const getMetaDescription = (input) => {
  const match = input.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']*)["'][^>]*>/i);
  return match ? match[1].replace(/\s+/g, " ").trim() : "";
};

const getFirstH1 = (input) => {
  const match = input.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
  return match
    ? match[1].replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim()
    : "";
};

const stripHtml = (input) =>
  input
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim();

const pageTitle = websiteBlocked ? "" : getTitle(htmlString);
const metaDescription = websiteBlocked ? "" : getMetaDescription(htmlString);
const h1 = websiteBlocked ? "" : getFirstH1(htmlString);
const websiteText = websiteBlocked ? "" : stripHtml(htmlString).slice(0, 3000);

return {
  json: {
    ...prep,
    page_title: pageTitle,
    meta_description: metaDescription,
    h1,
    website_text: websiteText,
    website_blocked: websiteBlocked,
    shop_notes: Array.isArray(prep.shop_notes) ? prep.shop_notes : [],
    language_hint: (prep.language_hint ?? "").toString().trim()
  }
};

const data = $json ?? {};

const companyName = (data.company_name || "").toLowerCase();
const websiteUrl = (data.website_url || "").toLowerCase();
const contactEmail = (data.contact_email || "").toLowerCase();
const firstName = (data.contact_first_name || "").toLowerCase();
const lastName = (data.contact_last_name || "").toLowerCase();
const title = (data.contact_title || "").toLowerCase();

const organizationCountry = (data.organization_country || "").toLowerCase();
const contactCountry = (data.contact_country || "").toLowerCase();
const languageHint = (data.language_hint || "").toLowerCase();

const pageTitle = (data.page_title || "").toLowerCase();
const metaDescription = (data.meta_description || "").toLowerCase();
const websiteText = (data.website_text || "").toLowerCase();

const combinedCore = [
  companyName,
  websiteUrl,
  contactEmail,
  firstName,
  lastName,
  title,
  organizationCountry,
  contactCountry
].join(" ");

const combinedWebsite = [
  pageTitle,
  metaDescription,
  websiteText,
  languageHint
].join(" ");

let deScore = 0;
let enScore = 0;

// Starke DACH-Signale
const strongDeSignals = [
  ".de",
  ".at",
  ".ch",
  "gmbh",
  "gmbh & co",
  "kg",
  "ag",
  "e.k.",
  "deutschland",
  "germany",
  "österreich",
  "austria",
  "schweiz",
  "switzerland"
];

for (const signal of strongDeSignals) {
  if (combinedCore.includes(signal)) deScore += 4;
}

// DACH-Länder aus CRM / Apollo
if (
  organizationCountry.includes("germany") ||
  organizationCountry.includes("deutschland") ||
  organizationCountry.includes("austria") ||
  organizationCountry.includes("österreich") ||
  organizationCountry.includes("switzerland") ||
  organizationCountry.includes("schweiz") ||
  contactCountry.includes("germany") ||
  contactCountry.includes("deutschland") ||
  contactCountry.includes("austria") ||
  contactCountry.includes("österreich") ||
  contactCountry.includes("switzerland") ||
  contactCountry.includes("schweiz")
) {
  deScore += 6;
}

// Deutsche Website-Signale nur schwach werten
const weakDeSignals = [
  "impressum",
  "datenschutz",
  "versand",
  "rückgabe",
  "kontakt",
  "warenkorb",
  "herren",
  "damen"
];

for (const signal of weakDeSignals) {
  if (combinedWebsite.includes(signal)) deScore += 1;
}

// Klare nicht-DACH-Signale -> eher Englisch
const nonDachSignals = [
  ".es",
  ".fr",
  ".it",
  ".nl",
  ".be",
  ".dk",
  ".se",
  ".no",
  ".fi",
  ".co.uk",
  "spain",
  "españa",
  "espana",
  "france",
  "italy",
  "netherlands",
  "belgium",
  "denmark",
  "sweden",
  "norway",
  "finland",
  "united kingdom",
  "uk"
];

for (const signal of nonDachSignals) {
  if (combinedCore.includes(signal)) enScore += 4;
}

// Internationale / spanische / romanische Namen nur leicht Richtung Englisch
const likelyNonGermanNames = [
  "laura",
  "jimenez",
  "soler",
  "nikolaos",
  "muhammed",
  "nicola",
  "simone"
];

if (likelyNonGermanNames.includes(firstName)) enScore += 1;
if (likelyNonGermanNames.includes(lastName)) enScore += 1;

// language_hint nur schwach werten, nie dominant
if (languageHint === "de") deScore += 1;
if (languageHint === "en") enScore += 1;

// Standard:
let language_guess = "en";

// Deutsch nur bei klaren DACH-Signalen
if (deScore >= 4 && deScore > enScore) {
  language_guess = "de";
}

return {
  json: {
    ...data,
    language_guess,
    debug_de_score: deScore,
    debug_en_score: enScore
  }
};

