function safeParseAgentOutput(raw) {
  if (!raw) return {};

  // Falls bereits Objekt
  if (typeof raw === 'object' && !Array.isArray(raw)) {
    return raw;
  }

  let text = String(raw).trim();
  if (!text) return {};

  // Markdown-Codefences entfernen
  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  // Falls vor/nach dem JSON noch Text steht:
  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    text = text.slice(firstBrace, lastBrace + 1);
  }

  return JSON.parse(text);
}

function normalizeNotes(value) {
  if (Array.isArray(value)) {
    return value
      .map(v => String(v || '').trim())
      .filter(Boolean);
  }

  if (typeof value === 'string' && value.trim()) {
    return value
      .split('\n')
      .map(v => v.replace(/^[-•]\s*/, '').trim())
      .filter(Boolean);
  }

  return [];
}

function normalizeUrl(url) {
  const value = String(url || '').trim();
  if (!value) return '';

  if (/^https?:\/\//i.test(value)) return value;

  return `https://${value}`;
}

const prep = { ...$json };
const rawOutput = prep.output || '';

let parsed = {};
let parseError = '';

try {
  parsed = safeParseAgentOutput(rawOutput);
} catch (err) {
  parseError = String(err.message || err);
  parsed = {};
}

const websiteUrl =
  normalizeUrl(parsed.website_url) ||
  normalizeUrl(prep.website_url) ||
  normalizeUrl(prep.website_url_hint) ||
  '';

const shopNotes = normalizeNotes(parsed.shop_notes);

const languageHintRaw = String(parsed.language_hint || '').trim().toLowerCase();
const languageHint =
  languageHintRaw === 'de' || languageHintRaw === 'en'
    ? languageHintRaw
    : '';

return {
  json: {
    ...prep,
    website_url: websiteUrl,
    shop_notes: shopNotes,
    language_hint: languageHint,
    website_found_by_search: !!websiteUrl,

    // Debug
    debug_parse_error: parseError,
