function findOrgArray(root) {
  const directCandidates = [
    'organizations',
    'accounts',
    'results',
    'data',
    'companies',
    'mixed_companies',
    'items'
  ];

  for (const key of directCandidates) {
    if (Array.isArray(root?.[key]) && root[key].length) {
      return root[key];
    }
  }

  // eine Ebene tiefer suchen
  for (const [key, value] of Object.entries(root || {})) {
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      for (const nestedKey of directCandidates) {
        if (Array.isArray(value?.[nestedKey]) && value[nestedKey].length) {
          return value[nestedKey];
        }
      }
    }
  }

  // letzte Rettung: erste brauchbare Objekt-Array-Struktur nehmen
  for (const [key, value] of Object.entries(root || {})) {
    if (Array.isArray(value) && value.length && typeof value[0] === 'object') {
      return value;
    }
  }

  return [];
}

